import pathlib,re
names=['CURO','Clickstream','DOMINI','DYNTEK','EcoScience','LEGACY','LOGANS','LOOKSMART','MERCATA','NOVO','ULTRAGENYX','INTRICON','AMERICAS','TEARDROP']
for f in sorted(pathlib.Path('/docs').glob('*.txt')):
 if not any(f.name.startswith(n) for n in names):continue
 lines=f.read_text().replace('\\u00a0',' ').splitlines();page='?'; hits=set()
 for i,l in enumerate(lines):
  if re.search('terminat|cancel|resign',l,re.I):hits.update(range(max(0,i-3),min(len(lines),i+7)))
 print('\\nFILE',f.name[:-4])
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m:page=m[1]
  if i in hits: print(page,l)
